program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seed = next(((r, c) for r in range(h) for c in range(w) if grid[r][c] == 3), None)
    if seed is None:
        return out
    sr, sc = seed
    pattern = {
        -4: [-4, -2, -1, 0, 1, 2, 3, 4],
        -3: [-4, -2, 4],
        -2: [-4, -2, 0, 1, 2, 4],
        -1: [-4, -2, 0, 2, 4],
         0: [-4, -2, 0, 2, 4],
         1: [-4, -2, 2, 4],
         2: [-4, -2, -1, 0, 1, 2, 4],
         3: [-4, 4],
         4: [-4, -3, -2, -1, 0, 1, 2, 3, 4],
    }
    cells = set()
    for dr, offsets in pattern.items():
        for dc in offsets:
            r, c = sr + dr, sc + dc
            if 0 <= r < h and 0 <= c < w:
                cells.add((r, c))
    # The 2s block the pattern; only the 4-connected part containing the seed is painted.
    allowed = {p for p in cells if grid[p[0]][p[1]] != 2}
    if seed in allowed:
        reached = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for p in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if p in allowed and p not in reached:
                    reached.add(p)
                    stack.append(p)
        for r, c in reached:
            out[r][c] = 3
    if not any(2 in row for row in grid) and sr + 6 < h:
        for c in range(w):
            out[sr + 6][c] = 3
    return out
'''
